      create procedure sWithOptions
	      with recompile, execute as owner
      as
	      -- there are options.
	      select * from sys.tables;
	      return 0;

      alter procedure dbo.ASimpleTestProcedure(
	        @NumberOfLines int, 
          @Two varchar(3) = 'abc', 
          @Three decimal(10,3),
          @Result datetime2(2) /*input*/output
      )
      as    
      begin
          set nocount on;
          set @Result = PARSE('Monday, 13 December 2010' AS datetime2 USING 'en-US');
          select top(@NumberOfLines) @Two, @Three, * from sys.databases;
          return 0;
      end
